CREATE TABLE IF NOT EXISTS gis_cross_validation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), primary_dataset_id uuid NOT NULL, comparison_dataset_name text NOT NULL, comparison_source_url text, comparison_version text, comparison_authority_status text NOT NULL DEFAULT 'Reference', methodology text NOT NULL, status text NOT NULL DEFAULT 'Pending', feature_count_primary integer NOT NULL DEFAULT 0, feature_count_comparison integer NOT NULL DEFAULT 0, matched_count integer NOT NULL DEFAULT 0, mismatch_count integer NOT NULL DEFAULT 0, tolerance_note text, result_summary text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_feature_crosswalks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), validation_run_id uuid NOT NULL REFERENCES gis_cross_validation_runs(id) ON DELETE CASCADE, primary_area_code text NOT NULL, primary_area_name text NOT NULL, comparison_area_code text, comparison_area_name text, match_status text NOT NULL DEFAULT 'Pending', geometry_comparison_status text NOT NULL DEFAULT 'Pending', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_cv_runs_dataset ON gis_cross_validation_runs(primary_dataset_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_feature_crosswalk_run ON gis_feature_crosswalks(validation_run_id,match_status);